"""สร้าง db/78_quiz_recall300.sql — ข้อสอบพื้นฐานเคมีเน้นจำ 300 ข้อ สำหรับควิซประจำวัน (quiz_questions, ทุกห้อง)"""
import os, re, json, random, collections
SUB = str.maketrans("0123456789+-", "₀₁₂₃₄₅₆₇₈₉₊₋"); SUP = str.maketrans("0123456789+-", "⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻")
def U(s):
    s = re.sub(r"\^([0-9]*[+-])", lambda m: m.group(1).translate(SUP), s)
    return re.sub(r"(?<=[A-Za-z\)])(\d+)", lambda m: m.group(1).translate(SUB), s)
def seed(s):
    h = 11
    for c in s: h = (h * 131 + ord(c)) % 1000003
    return h
Q = []
def H(topic, q, ok, wrong, ex):
    ch = [ok] + list(wrong); assert len(ch) == 4 and len(set(ch)) == 4, (q, ch)
    order = list(range(4)); random.Random(seed(q)).shuffle(order)
    Q.append((topic, q, [ch[i] for i in order], order.index(0), ex))
def pick(pool, ok, n, key):
    r = random.Random(seed(key)); c = [x for x in pool if x != ok]; r.shuffle(c); return c[:n]

