# ---------- เขียนไฟล์ ----------
here = os.path.dirname(os.path.abspath(__file__)); db = os.path.join(here, "..", "db")
exist = ""
for f in os.listdir(db):
    if f.endswith(".sql") and f not in ("setup_all.sql", "78_quiz_recall300.sql"): exist += open(os.path.join(db, f), encoding="utf-8").read()
dups = [q for _, q, *_ in Q if q in exist]
Q[:] = [x for x in Q if x[1] not in exist]
assert len({q for _, q, *_ in Q}) == len(Q), "ซ้ำในชุดใหม่: " + str([q for q, n in collections.Counter(x[1] for x in Q).items() if n > 1])
print("ซ้ำกับข้อเดิมในไฟล์ SQL:", len(dups), dups[:5])
import sys
TARGET = int(os.environ.get("N", 300))
print("total", len(Q), dict(collections.Counter(t for t, *_ in Q)))
if len(Q) == TARGET or os.environ.get("FORCE"):
    out = ["-- 78: ข้อสอบพื้นฐานเคมี เน้นจำ " + str(len(Q)) + " ข้อ สำหรับควิซประจำวัน (v2.19) · รันซ้ำได้ (ข้อที่หัวข้อ + โจทย์ซ้ำจะไม่ถูกเพิ่ม)",
           "--  · ทุกห้อง (class_id ว่าง) · ปิดข้อที่ไม่เหมาะกับห้องได้ในแท็บ 🎮 มินิเกม", "--  · " + " · ".join(f"{t} {n}" for t, n in collections.Counter(t for t, *_ in Q).items()), ""]
    for t, q, ch, a, ex in Q:
        out.append("insert into quiz_questions (topic, question, a, b, c, d, answer, explain)\nselect $t$%s$t$, $t$%s$t$, $t$%s$t$, $t$%s$t$, $t$%s$t$, $t$%s$t$, %d, $t$%s$t$\nwhere not exists (select 1 from quiz_questions where topic = $t$%s$t$ and question = $t$%s$t$);" % (t, q, ch[0], ch[1], ch[2], ch[3], a, ex, t, q))
    open(os.path.join(db, "78_quiz_recall300.sql"), "w", encoding="utf-8").write("\n".join(out) + "\n"); print("written")
